### 5.2 核心载荷精确结构体规约

以下结构体在物理线缆上使用 Little-Endian 端序传输，使用 `__attribute__((packed))` 约束紧凑物理尺寸。

#### 1. 确认与否定应答载荷 (`0x00` / `0x06`)
```c
// CMD_ACK 载荷 (0x00, 固定 4 字节，彻底消除 2~4 字节歧义)
struct __attribute__((packed)) minimc_payload_ack {
    uint8_t  planner_buf_free;    // Marlin 规划器空闲槽位 (0~32)
    uint8_t  rx_fifo_free_units;  // 接收缓冲区物理空闲量 (以 64B 为单位)
    uint16_t reserved;            // 保留对齐补位，发送端置 0
};

// CMD_NACK 载荷 (0x06, 固定 3 字节)
struct __attribute__((packed)) minimc_payload_nack {
    uint8_t  error_code;          // 标准错误码 (见下文枚举)
    uint16_t expected_seq;        // 接收端期望的下一个正确 16-bit seq
};

// 标准 NACK 错误码定义
enum {
    MINIMC_ERR_CRC                 = 0x01, // 帧校验和错误 (仅用于诊断统计，不回线缆 NACK)
    MINIMC_ERR_MTU_EXCEEDED        = 0x02, // 载荷长度超过端点或协议上限
    MINIMC_ERR_MTU_EXCEEDED        = 0x02, // 载荷长度超过端点或协议上限
    MINIMC_ERR_SEQ_OUT_OF_WINDOW   = 0x03, // 序号超前越界 (乱序)
    MINIMC_ERR_UNKNOWN_CMD         = 0x04, // 不支持的操作码
    MINIMC_ERR_DEVICE_BUSY         = 0x05, // 接收端繁忙 (队列已满或非空闲安全态)
    MINIMC_ERR_COMMAND_REJECTED    = 0x06, // 命令参数/Trailer/内块CRC校验失败被拒绝
    MINIMC_ERR_ROUTING_CONGESTION  = 0x07, // 路由节点拥塞丢弃
    MINIMC_ERR_STALE_EXPIRED       = 0x08, // 历史重传已过时脱离缓存
    MINIMC_ERR_SEQ_AMBIGUOUS       = 0x09, // 序号处于半周期分界盲区
    MINIMC_ERR_OTA_ERASE_FAIL      = 0x10, // Flash 扇区擦除失败
    MINIMC_ERR_OTA_WRITE_FAIL      = 0x11, // Flash 编程写入或回读比对失败
    MINIMC_ERR_OTA_CRC_MISMATCH    = 0x12, // 固件全量 CRC32 校验不匹配
    MINIMC_ERR_OTA_INVALID_OFFSET  = 0x13, // 固件数据分块偏移不连续或越界
    MINIMC_ERR_OTA_IMAGE_OVERSIZE  = 0x14  // 固件尺寸超过 Flash 分区限制 (如 TH > 236KB)
};
```

#### 2. 版本协商与运行模式识别报文 (`0x01 CMD_GET_VERSION` / `0x02 CMD_VERSION_REPORT`)
`CMD_GET_VERSION` 无载荷（$L=0$）。`CMD_VERSION_REPORT` 为固定 16 字节：
```c
struct __attribute__((packed)) minimc_payload_version_report {
    uint8_t  proto_ver_major;     // 协议主版本 (2)
    uint8_t  proto_ver_minor;     // 协议次版本 (0)
    uint8_t  firmware_major;      // 固件主版本 (App 或 Boot 主版本)
    uint8_t  firmware_minor;      // 固件次版本 (App 或 Boot 次版本)
    uint32_t boot_id;             // 动态启动会话代次标识 (每次复位/启动必须变化)
    uint32_t git_commit_short;    // Git Commit 缩写哈希 (小端整型)
    uint32_t capability_flags;    // 节点能力集与运行模式位图 (见下方规约)
};
```
* **`capability_flags` 位图契约**：
  * **`Bit 31` (`0x80000000U`)**：运行模式权威标志——`0` = **App 业务态 (`APP_MODE`)**，`1` = **Bootloader 引导升级态 (`BOOT_MODE`)**；
  * 当 `Bit 31 == 1` (`BOOT_MODE`) 时：`Bit 30 = 1` 表示支持 `128B ATSG Trailer` 擦除前准入，`Bit 29 = 1` 表示支持首块 512B SRAM 延迟提交与 Anchor 保护，`Bits 16..23` 为最大分块除以 64（`512B -> 0x08`），`Bits 0..15` 为板卡硬件标识低 16 位（MC Boot = `0xC0080435U`，TH Boot = `0xE0080423U`）。

